                                # Look for actual key patterns
                                keys = re.findall(r'([a-zA-Z0-9_-]{20,})', content)
                                if keys:
                                    found_keys.extend([(str(file_path), key) for key in keys[:3]])
                    except:
                        pass

if found_keys:
    print(f"✅ Found {len(found_keys)} potential API keys:")
    for file_path, key in found_keys[:10]:
        print(f"  - {file_path}: ...{key[-10:]}")
else:
    print("❌ No API keys found in additional locations")

